        roles = list(
            UserRole.objects.filter(user_id=user.id, revoked_at__isnull=True).order_by(
                "-is_primary", "granted_at"
            )
        )
        values = []
        if any(role.role == "tenant" for role in roles):
            values.append("find_property")
        if any(role.role in {"landlord", "agent", "property_manager"} for role in roles):
            values.append("manage_property")
        primary_role = next((role.role for role in roles if role.is_primary), None)
        primary_intent = (
            "manage_property"
            if primary_role in {"landlord", "agent", "property_manager"}
            else "find_property"
        )
        for value in values:
            UserIntent.objects.get_or_create(
                user_id=user.id,
                intent=value,
                defaults={"is_primary": value == primary_intent},
            )


